import type { Cefr, ChartVisual, ContentSection, SpatialVisual, StoredContent, VisualAsset } from "../../../shared/types.js";

const generatedAt = "2026-10-11T00:00:00.000Z";
const report = "Summarise the information by selecting and reporting the main features, and make comparisons where relevant.";
const cefr = (band: number): Cefr => band < 4.5 ? "A2" : band < 6 ? "B1" : band < 7.5 ? "B2" : "C1";
const bands = [3, 3.5, 4, 4.5, 5, 5.5, 6, 6.5, 7, 7.5, 8];
const instructions = (task: 1 | 2) => task === 1
  ? "You should spend about 20 minutes on this task. Write at least 150 words."
  : "You should spend about 40 minutes on this task. Write at least 250 words. Give reasons for your answer and include any relevant examples from your own knowledge or experience.";
type Pack = { title: string; topic: string; family: string; task: 1 | 2; text: string; testType: "academic" | "general" | "both"; visuals?: VisualAsset[]; guidance: string };
function chart(id: string, type: ChartVisual["type"], title: string, unit: string, series: string[], rows: [string, ...number[]][]): ChartVisual {
  return { id: `fresh-w-${id}`, type, title, unit, series, rows: rows.map(([label, ...values]) => ({ label, values })) };
}
function map(id: string, title: string, places: [string, number, number, number, number][], road: [number, number][] = [[20, 425], [740, 425]]): SpatialVisual {
  const asset: SpatialVisual = { id: `fresh-w-${id}`, type: "map", title, width: 760, height: 480,
    labels: [{ id: `${id}-north`, text: "North ↑", x: 680, y: 28 }, ...places.map(([text, x, y], i) => ({ id: `${id}-label-${i}`, text, x: x + 10, y: y + 30 }))],
    areas: places.map(([text, x, y, width, height], i) => ({ id: `${id}-area-${i}`, x, y, width, height, fill: /pond|garden|wood|reed|green|meadow|grove|wetland/i.test(text) ? "#d8e8c8" : "#eadfce" })),
    paths: [{ id: `${id}-access`, points: road, style: "road" }] };
  if (id.startsWith("island-")) {
    asset.paths!.push({ id: `${id}-river`, points: [[20, 20], [20, 460], [740, 460], [740, 20]], style: "river" });
    asset.labels.push({ id: `${id}-river-label`, text: "River", x: 55, y: 451 }, { id: `${id}-bridge-label`, text: "Bridge", x: 400, y: 450 });
  }
  if (id.startsWith("school-yard-")) {
    asset.areas!.push({ id: `${id}-gate`, x: 365, y: 418, width: 30, height: 15, fill: "#907653" });
    asset.labels.push({ id: `${id}-gate-label`, text: "Southern gate", x: 325, y: 453 });
  }
  if (id.startsWith("mock-quay")) {
    asset.paths!.push({ id: `${id}-river`, points: [[20, 450], [740, 450]], style: "river" });
    asset.labels.push({ id: `${id}-river-label`, text: "River", x: 335, y: 476 });
  }
  return asset;
}
function process(id: string, title: string, stages: string[], returnTo?: number): SpatialVisual {
  const nodes = stages.map((text, i) => {
    const angle = -Math.PI / 2 + i * 2 * Math.PI / stages.length;
    return { id: `${id}-stage-${i}`, text,
      x: returnTo !== undefined ? 385 + 270 * Math.cos(angle) - 90 : 20 + (Math.floor(i / 3) % 2 ? 2 - i % 3 : i % 3) * 250,
      y: returnTo !== undefined ? 370 + 290 * Math.sin(angle) - 45 : 25 + Math.floor(i / 3) * 160,
      width: returnTo !== undefined ? 180 : 225, height: returnTo !== undefined ? 90 : 110 };
  });
  const connections = nodes.slice(1).map((node, i) => ({ from: nodes[i]!.id, to: node.id }));
  if (returnTo !== undefined) connections.push({ from: nodes.at(-1)!.id, to: nodes[returnTo]!.id });
  return { id: `fresh-w-${id}`, type: "process", title, width: 770, height: returnTo !== undefined ? 740 : Math.ceil(stages.length / 3) * 160 + 30, labels: [], nodes, connections };
}
function academic(title: string, topic: string, family: string, text: string, visuals: VisualAsset[], guidance: string): Pack {
  return { title, topic, family, task: 1, text: `${text} ${report}`, testType: "academic", visuals, guidance };
}

