const letter = (title: string, topic: string, tone: string, situation: string, bullets: [string, string, string], guidance: string): Pack => ({ title, topic, family: `letter-${tone}`, task: 1, testType: "general", text: `${situation}\n\nWrite a letter to the person specified. In your letter:\n• ${bullets[0]}\n• ${bullets[1]}\n• ${bullets[2]}\n\nYou do not need to write any addresses.`, guidance });
