function base(id: string, band: number, topic: string): Omit<StoredContent, "title" | "description" | "sections"> {
  return { id, skill: "writing", band, cefr: cefr(band), topic, testType: "both", durationMinutes: 20, format: "lesson", questions: [], vocabularyIds: [], tags: ["fresh-reset-v6", "original-prompt"], source: "ai", quality: "ai-unreviewed", createdAt: generatedAt,
    estimatedDifficulty: { band, cefr: cefr(band), basis: "Practice target estimated from expected organisation, linguistic control and degree of support; the authentic task length is retained at every target. Not empirically calibrated." },
    provenance: { method: "ai-assisted", version: "fresh-reset-v6", generatedAt }, review: { status: "unreviewed", checks: [], limitations: ["Original AI-generated practice. Not an official IELTS question or independently examiner-reviewed difficulty calibration."] },
    objectives: ["Address all parts of the task with relevant information.", "Organise paragraphs logically and use accurate, appropriate language."], errorTypes: ["task-coverage", "paragraph-coherence", "lexical-precision", "grammatical-control"] };
}
function section(pack: Pack, id: string): ContentSection {
  // A lesson can also be opened in Exam mode or selected for a Duo gate. Keep
  // the stimulus clean; practice guidance belongs to the existing mode-aware
  // objectives panel rather than to the examiner's task text.
  return { id, title: `Task ${pack.task} · ${pack.family}`, task: pack.task, text: pack.text, instructions: instructions(pack.task), ...(pack.visuals ? { visuals: pack.visuals } : {}) };
}
export const freshWritingLessons: StoredContent[] = [...academicLessons, ...letterLessons, ...essayLessons].map((pack, i) => {
  const id = `fresh-w-lesson-${String(i + 1).padStart(3, "0")}`; const band = bands[i % bands.length]!;
  return { ...base(id, band, pack.topic), title: pack.title, description: `New ${pack.testType === "general" ? "General Training" : pack.task === 1 ? "Academic" : "IELTS"} Task ${pack.task} practice with authentic ${pack.task === 1 ? "150" : "250"}-word minimum; estimated target band ${band}.`, testType: pack.testType, durationMinutes: pack.task === 1 ? 20 : 40,
    objectives: ["Address all parts of the task with relevant information.", "Organise paragraphs logically and use accurate, appropriate language.", pack.guidance],
    tags: ["fresh-reset-v6", `task-${pack.task}`, `writing-family:${pack.family}`, `target-band:${band}`], sections: [section(pack, `${id}-task${pack.task}`)] };
});
export const freshWritingMocks: StoredContent[] = [...academicMockTasks, ...generalMockTasks].map((task1, i) => {
  const id = `fresh-w-mock-${String(i + 1).padStart(2, "0")}`; const band = [3, 4, 5, 6, 7, 7.5, 8][i % 7]!;
  return { ...base(id, band, `Full writing · ${task1.topic}`), title: `${task1.testType === "academic" ? "Academic" : "General Training"} Writing · New test ${i + 1}`, description: "A wholly new 60-minute test: Task 1 (at least 150 words) and Task 2 (at least 250 words). Task 2 carries twice the weight. No planning note or model answer is shown.", testType: task1.testType, durationMinutes: 60, format: "full-mock", tags: ["fresh-reset-v6", "independent-mock", `writing-family:${task1.family}`, `essay-family:${mockEssays[i]!.family}`], sections: [section(task1, `${id}-task1`), section(mockEssays[i]!, `${id}-task2`)] };
});

